    /// <summary>
    ///
    /// </summary>
    /// <param name="sender"></param>
    /// <param name="e"></param>
    [FormDataFieldEventHandler(formDataFieldStr(PurchTable, InventDim, InventSiteId), FormDataFieldEventType::Modified), SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void InventSiteId_OnModified(FormDataObject sender, FormDataFieldEventArgs e)
    {
        InventItemPurchSetup    inventItemPurchSetup;
        FormDataSource          datasource      = sender.dataSource().formRun().dataSource(formDataSourceStr(PurchTable,PurchLine)) as FormDataSource;
        
        PurchLine               purchLine       = datasource.cursor();
        InventDim               inventDimLoc    = sender.datasource().cursor();
        InventDim               inventDimPurch;
       
        //MPJ_17845_PBMSProductMDRItemSite on 04 March 2022 by Sathish - Start
        //inventItemPurchSetup = InventItemPurchSetup::find(purchLine.ItemId ,purchLine.InventDimId);
        select firstonly inventItemPurchSetup 
            where inventItemPurchSetup.ItemId == purchLine.ItemId 
                join inventDimPurch 
                    where inventDimPurch.inventDimId == inventItemPurchSetup.InventDimId
                        &&  inventDimPurch.InventSiteId == inventDimLoc.InventSiteId;

        purchLine.PurchUnit  = inventItemPurchSetup.METPurchUnit;
        //MPJ_17845_PBMSProductMDRItemSite - End
    }

    /// <summary>
    /// MPJ_12065_RestrictCostchangesOnPOs on 15 Feb 2022 by chaminda
    /// </summary>
    /// <param name="_sender"> Get form run object </param>    
    private static void checkCostOverride(FormDataObject _sender)
    {
        FormDataSource  formDataSource  = _sender.datasource();
        PurchLine       purchLine       = formDataSource.cursor();
        VendParameters  vendParameters  = VendParameters::find();
        DictTable       dt = new SysDictTable(tableNum(PurchLine));
        DictField       dictField;
        if(purchLine && vendParameters.METEnablePOCostUpdateRestrictions)
        {
            PurchLine purchLineOrig = purchLine.orig();
            if(PurchLine)
            {
                if(purchLine.LineAmount != purchLineOrig.LineAmount)
                {
                    if(((purchLine.LineAmount-purchLineOrig.LineAmount)/purchLineOrig.LineAmount)*100 > vendParameters.METPOCostChangePercentAllowed)
                    {                   
                    
                        if(purchLine.PurchPrice != purchLineOrig.PurchPrice)
                        {                        
                            dictField   = dt.fieldObject(fieldNum(PurchLine,PurchPrice));                  
                            warning(strFmt("@MET:POCostOverrideWarning",vendParameters.METPOCostChangePercentAllowed,dictField.label(), purchLine.ItemId));                        
                        }
                        if(purchLine.LineAmount != purchLineOrig.LineAmount)
                        {
                            dictField   = dt.fieldObject(fieldNum(PurchLine,LineAmount));
                            warning(strFmt("@MET:POCostOverrideWarning",vendParameters.METPOCostChangePercentAllowed,dictField.label(), purchLine.ItemId));
                        }
                    }
                }
            }
        }

    }

    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields on 30 Mar 2022 by chaminda
    /// Call the metMultiSelectLookupBuilder.buildLookup method with parameters
    /// </summary>
    /// <param name="sender"> Get form control object</param>
    /// <param name="e"> Get form data source args</param>
   
    [FormControlEventHandler(formControlStr(PurchTable, METPurchTable_POSubMode), FormControlEventType::Lookup),
     SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void METPurchTable_POSubMode_OnLookup(FormControl sender, FormControlEventArgs e)
    {        
        SysDictEnum                         sysDictEnum = new SysDictEnum(enumNum(METPOSubMode));        
        FormStringControl                   formStringControl = sender.formRun().design().controlName(formControlStr(PurchTable, METPurchTable_POSubMode));
        FormDataSource metPurchTable_ds =sender.formRun().dataSource(formDataSourceStr(PurchTable, METPurchTable));

        METMultiSelectLookupBuilder metMultiSelectLookupBuilder = new METMultiSelectLookupBuilder();
        metMultiSelectLookupBuilder.buildLookup(sender,e,metPurchTable_ds,formStringControl,sysDictEnum.id());
       
    }

    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
    /// </summary>
    /// <param name="sender">Get from form data source</param>
    /// <param name="e">args</param>
    [FormDataSourceEventHandler(formDataSourceStr(PurchTable, METPurchTable), FormDataSourceEventType::ValidatingWrite), SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void METPurchTable_OnValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun                 formRun        = sender.formRun();
        METPurchTable           METPurchTable = formRun.dataSource(formDataSourceStr(PurchTable,METPurchTable)).cursor();
        FormDataSource          purchTabledatasource = formRun.dataSource(formDataSourceStr(PurchTable,purchTable));
        purchTable              purchTable = purchTabledatasource.cursor();

        if(purchTable.recid && !METPurchTable.PurchTable)
        {
            PurchTable.packMETPurchTable(METPurchTable);
            METPurchTable.SysExtensionSerializerExtensionMap::insertAfterBaseTable(PurchTable);
            METPurchTable.initFromVendSiteSettingsSetup();
        }
    }

    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
    /// </summary>
    /// <param name="sender">Get from form data source</param>
    /// <param name="e">args</param>
    [FormDataSourceEventHandler(formDataSourceStr(PurchTable, PurchLine), FormDataSourceEventType::Writing), SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
        public static void PurchLine_OnWritting(FormDataSource sender, FormDataSourceEventArgs e)
    {
        FormRun             formRun         = sender.formRun();
        PurchLine           purchLine       = formRun.dataSource(formDataSourceStr(PurchTable,PurchLine)).cursor();

        METPurchTable       METPurchTable   = formRun.dataSource(formDataSourceStr(PurchTable,METPurchTable)).cursor();

        if(METPurchTable.POPromotionIHG && !purchLine.RecId)
        {
            purchLine.METPOLinePromotionIHG = METPurchTable.POPromotionIHG;
        }

        //Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2 --> Begin
        if(!purchLine.RecId && !purchLine::exist(purchLine.purchid))
        {
            METPlannerCode plannerCode;
            MetItemSiteSettingsSetup    ItemSiteSettingsSetup;
            InventDim               inventDimLoc    = formRun.dataSource(formDataSourceStr(PurchTable,InventDim)).cursor();

            select firstonly1 PlannerCode from ItemSiteSettingsSetup
                where ((ItemSiteSettingsSetup.ItemId == purchLine.ItemId && ItemSiteSettingsSetup.InventSiteId == inventDimLoc.InventSiteId)
                 || ItemSiteSettingsSetup.ItemId == purchLine.ItemId)
                 && ItemSiteSettingsSetup.PlannerCode;

            METPurchTable.POPlannerCode = ItemSiteSettingsSetup.PlannerCode;
            if(METPurchTable && METPurchTable.validateWrite())
            {
                METPurchTable.Write();
            }
        }
        //Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2 --> End

    }

    /// <summary>
    /// MPJ_19962_MDRPOTransactionalMissingFields kavya 25/3/2022
    /// </summary>
    /// <param name="sender">Get from form data source</param>
    /// <param name="e">args</param>
    [FormDataSourceEventHandler(formDataSourceStr(PurchTable, PurchLine), FormDataSourceEventType::ValidatingWrite), SuppressBPWarningAttribute("BPParameterNotUsed", "@MET:BPParameterNotUsedMessage")]
    public static void PurchLine_OnValidatingWrite(FormDataSource sender, FormDataSourceEventArgs e)
    {
        var             args        = e as FormDataSourceCancelEventArgs;
        FormRun         formRun     = sender.formRun();
        PurchLine       purchLine   = formRun.dataSource(formDataSourceStr(PurchTable,PurchLine)).cursor();

        METPurchTable   METPurchTable = formRun.dataSource(formDataSourceStr(PurchTable,METPurchTable)).cursor();

        if(args != null && METPurchTable.POPromotionIHG && !purchLine.METPOLinePromotionIHG)
        {
            Valid ret = checkFailed("@MET:METPOPromotionValidation");
            args.cancel(ret);
        }
    }

    /// <summary>
    /// Added by kavya on 11/5/2022 for MPJ_19962_MDRPOTransactionalMissingFields - part 2
    /// TO update the change reason code for all the PO Line
    /// </summary>
    /// <param name="sender">Form control</param>
    /// <param name="e">args</param>
    [FormControlEventHandler(formControlStr(PurchTable, METUpdateAllPOChangeReasonCode), FormControlEventType::Clicking)]
    public static void METUpdateAllPOChangeReasonCode_OnClicking(FormControl sender, FormControlEventArgs e)
    {
        FormButtonControl   callerButton    = sender as FormButtonControl;  //Retrieves the button that we're reacting to
        FormRun             form            = callerButton.formRun(); //Gets the running formx
 
        FormDataSource  PurchTable_ds   = form.dataSource(formDataSourceStr(PurchTable, PurchTable)) as FormDataSource;
        PurchTable      PurchTable      = PurchTable_ds.cursor();

        Dialog      dialog;
        DialogField reasonCodeDF;

        dialog = new Dialog("@MET:METUpdateAllLinesReasonCode");

        reasonCodeDF = dialog.addField(extendedTypeStr(METChangeReasonCode));

        dialog.run();

        if (dialog.closedOk())
        {
            PurchLine purchline;

            update_recordset purchline
                setting METPOLineChangeReasonCode = reasonCodeDF.value()
            where purchline.purchid == PurchTable.PurchId;   
        }

    }
